const root = $input.first().json;
const execution = root.execution ?? {};
const workflow = root.workflow ?? {};
const error = execution.error ?? root.error ?? {};
const workflowName = workflow.name ?? execution.workflowName ?? 'unknown';
const executionId = execution.id ?? 'n/a';
const nodeName = execution.lastNodeExecuted ?? error.node ?? 'n/a';
const message = error.message ?? String(error) ?? 'Erro sem mensagem';
const startedAt = execution.startedAt ?? new Date().toISOString();
const n8nBase = ($env.N8N_BASE_URL || $env.WEBHOOK_URL || 'http://127.0.0.1:5678').replace(/\/$/, '');
const execUrl = `${n8nBase}/workflow/${workflow.id || ''}/executions/${executionId}`;
const text = [
  ':rotating_light: *Bethânia N8N — falha*',
  `*Workflow:* ${workflowName}`,
  `*Node:* ${nodeName}`,
  `*Erro:* ${message}`,
  `*Execution:* ${executionId}`,
  `*Quando:* ${startedAt}`,
  `*Link:* ${execUrl}`,
].join('\n');
const webhookUrl = ($env.BETHANIA_SLACK_WEBHOOK_URL || '').trim();
if (!webhookUrl) {
  throw new Error('BETHANIA_SLACK_WEBHOOK_URL não configurada');
}
return [{ json: { webhookUrl, text, workflowName, executionId, nodeName, message } }];
